1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	import '../../../../core/failure/failure.dart';
7	import '../../../../core/isolated_side_effect.dart';
8	import '../../../entries/domain/entities/entry.dart';
9	import '../../../entries/domain/usecases/save_chat_message_as_entry_use_case.dart';
10	import '../../domain/entities/bookmark_state.dart';
11	import '../../domain/entities/chat_message.dart';
12	import '../../domain/entities/chat_session.dart';
13	import '../../domain/entities/chat_stream_event.dart';
14	import '../../domain/repositories/chat_repository.dart';
15	import '../../domain/services/connectivity_watcher.dart';
16	import 'chat_state.dart';
17	
18	/// Drives `ChatScreen` — a DI `lazySingleton` (Code Map, mirroring
19	/// `MeusRegistrosCubit`): long-lived, so returning to Home/Chat within the
20	/// same app session never re-bootstraps the session/history it already
21	/// loaded (`init()`'s own no-op guard below).
22	class ChatCubit extends Cubit<ChatState> {
23	  ChatCubit(
24	    this._repository,
25	    this._connectivityWatcher,
26	    this._saveChatMessageAsEntryUseCase,
27	  ) : super(const ChatBootstrapLoading()) {
28	    // spec-6-3 — subscribes immediately (not gated on bootstrap), so the
29	    // very first connectivity read is never missed while a slow
30	    // `init()` is still in flight; `_handleConnectivityChange` itself is
31	    // a no-op against anything but `ChatReady` until bootstrap resolves,
32	    // `_isOffline` still being tracked below so a later `ChatReady`
33	    // (bootstrap, `switchSession`, `startNewSession`) picks up whatever
34	    // the device's status already was.
35	    _connectivitySubscription = _connectivityWatcher.watch().listen(
36	      _handleConnectivityChange,
37	      onError: (Object _, StackTrace _) {
38	        // RNF09: a connectivity-watch error (e.g. the platform channel
39	        // being unavailable — no device/simulator exists yet, AGENTS.md)
40	        // must never escape the cubit; `_isOffline` simply keeps
41	        // whatever value it last had (`false` if this is the very first
42	        // read) instead of crashing.
43	      },
44	    );
45	  }
46	
47	  final ChatRepository _repository;
48	  final ConnectivityWatcher _connectivityWatcher;
49	
50	  /// spec-6-4 (RF10) — the shared use case AGENTS.md's RF10 rule requires;
51	  /// never `EntriesRepository`, never anything under `entries/data/`/
52	  /// `entries/presentation/` (Boundaries).
53	  final SaveChatMessageAsEntryUseCase _saveChatMessageAsEntryUseCase;
54	
55	  StreamSubscription<bool>? _connectivitySubscription;
56	
57	  StreamSubscription<Either<Failure, ChatStreamEvent>>? _sendSubscription;
58	
59	  /// The in-flight [sendMessage]/[retryMessage]'s own completer, if any —
60	  /// [close] must complete it itself, since cancelling [_sendSubscription]
61	  /// alone never fires `onDone`/`onError` (review fix: `cancel()` alone
62	  /// left `sendMessage()`'s returned `Future` permanently unresolved when
63	  /// the cubit closed mid-send).
64	  Completer<void>? _sendCompleter;
65	
66	  /// Monotonic counter behind every locally generated [ChatUiMessage.id]
67	  /// (Code Map) — never the server's own message id (see `ChatStreamEvent`'s
68	  /// own doc on why `message_created`'s id goes unused here).
69	  int _localIdCounter = 0;
70	
71	  /// Whether a send/retry is actively in flight right now — tracked
72	  /// locally rather than by scanning [ChatState.messages] for a persisted
73	  /// `streaming` status, since a message loaded from history/cache can
74	  /// legitimately carry that same status (e.g. one left over from an
75	  /// earlier dropped response, the I/O matrix's own scenario) without a
76	  /// send actually being in progress; scanning for it would permanently
77	  /// disable the composer in that case. [retryMessage] reuses this exact
78	  /// guard verbatim (Boundaries: "a second retry while one is in flight —
79	  /// reuses `_isSending` verbatim"), so a retry and a send can never race
80	  /// each other either.
81	  bool _isSending = false;
82	
83	  /// An in-flight bootstrap, if any — reused by a concurrent `init()` call
84	  /// instead of starting a second bootstrap, so two near-simultaneous
85	  /// callers (e.g. two mounts before the first resolves) never both
86	  /// observe "no sessions" and both call `createSession()` (Boundaries:
87	  /// "silently ensure *one* Chat Session exists").
88	  Future<void>? _initFuture;
89	
90	  /// spec-6-3 — the device's last known online/offline status, as
91	  /// reported by [_connectivityWatcher], `true` meaning offline. Tracked
92	  /// independently of [ChatState] (unlike `_isSending`'s own UI-facing
93	  /// twin, [ChatReady.isOffline]) so a status learned before bootstrap
94	  /// resolves — or while the active session is being switched, neither of
95	  /// which touches this field — is never lost; every place that emits a
96	  /// fresh [ChatReady] (`_bootstrap`, [switchSession], [startNewSession])
97	  /// carries it forward explicitly.
98	  bool _isOffline = false;
99	
100	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
101	  /// `sessionId`, on `ChatCubit` (never Hive) — survives session switches
102	  /// within one app run, resets on restart." Lives on this long-lived
103	  /// `lazySingleton` cubit itself (Design Notes), never on [ChatReady] —
104	  /// a state value would otherwise have to be threaded through every
105	  /// unrelated `copyWith` call just to avoid losing it.
106	  final Map<String, double> _scrollOffsets = {};
107	
108	  /// Review fix (round 2) — [bookmarkMessage]'s own save outcome, keyed
109	  /// by the message's `serverId` (never the in-session [ChatUiMessage.id],
110	  /// which is only a local id until the server confirms it, Design Notes)
111	  /// so a save that resolves *after* the user has switched/started a
112	  /// session — [switchSession]/[startNewSession] replace [ChatReady.
113	  /// messages] wholesale and never cancel a bookmark save in flight,
114	  /// unlike [_cancelInFlightSend] for send/retry — is never silently
115	  /// dropped. [_fromDomain] applies it when a session's history is
116	  /// (re)loaded; same in-memory-only, never-persisted-across-restarts
117	  /// lifetime as [_scrollOffsets] above (Boundaries).
118	  final Map<String, BookmarkState> _bookmarkStateByServerId = {};
119	
120	  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
121	  /// exists (reuse the most recent from `chat-sessions-list`, else
122	  /// `chat-sessions-create` with no title)". A no-op once already
123	  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
124	  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
125	  /// from an earlier visit.
126	  Future<void> init() {
127	    if (state is ChatReady || isClosed) {
128	      return Future.value();
129	    }
130	    return _initFuture ??= _bootstrap().whenComplete(() => _initFuture = null);
131	  }
132	
133	  Future<void> _bootstrap() async {
134	    emit(const ChatBootstrapLoading());
135	
136	    final sessionsResult = await _repository.listSessions();
137	    if (isClosed) {
138	      return;
139	    }
140	    // Captured by the closures below so the resulting [ChatReady] can
141	    // carry every known session (Code Map: "capture resolved sessions
142	    // into the emitted ChatReady"), not just the one picked to reuse.
143	    List<ChatSession> sessions = const [];
144	    final Either<Failure, ChatSession> sessionResult = await sessionsResult
145	        .match((failure) async => left(failure), (fetchedSessions) async {
146	          if (fetchedSessions.isEmpty) {
147	            final createResult = await _repository.createSession();
148	            return createResult.match((failure) => left(failure), (session) {
149	              sessions = [session];
150	              return right(session);
151	            });
152	          }
153	          sessions = fetchedSessions;
154	          // "reuse the most recent" — defensively re-sorts rather than
155	          // trusting `listSessions()`'s own ordering (its offline-cache
156	          // fallback already sorts `updatedAt` desc, but the live
157	          // server response's own ordering isn't documented either
158	          // way). `tryParse` (never `parse`) — same crash-safe pattern as
159	          // `AppDrawer`'s own session sort (review finding "Crash risk in
160	          // the new `_ConversasSection` sort"): a malformed `updatedAt`
161	          // must never crash bootstrap itself, so it falls back to the
162	          // epoch and simply sorts last instead of throwing.
163	          final mostRecent = [...fetchedSessions]
164	            ..sort(
165	              (a, b) => (DateTime.tryParse(b.updatedAt) ?? DateTime(0))
166	                  .compareTo(DateTime.tryParse(a.updatedAt) ?? DateTime(0)),
167	            );
168	          return right(mostRecent.first);
169	        });
170	    if (isClosed) {
171	      return;
172	    }
173	
174	    await sessionResult.match(
175	      (failure) async {
176	        if (!isClosed) {
177	          emit(ChatBootstrapError(failure));
178	        }
179	      },
180	      (session) async {
181	        final messagesResult = await _repository.listMessages(session.id);
182	        if (isClosed) {
183	          return;
184	        }
185	        messagesResult.match(
186	          (failure) => emit(ChatBootstrapError(failure)),
187	          (messages) => emit(
188	            ChatReady(
189	              sessionId: session.id,
190	              messages: messages.map(_fromDomain).toList(),
191	              sessions: sessions,
192	              isOffline: _isOffline,
193	            ),
194	          ),
195	        );
196	      },
197	    );
198	  }
199	
200	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
201	  /// `sessionId`" — `ChatScreen`'s own `ScrollController` listener calls
202	  /// this on every scroll update, so whichever offset a session was last
203	  /// left at is always the one [switchSession] hands back when that
204	  /// session becomes active again.
205	  void recordScrollOffset(String sessionId, double offset) {
206	    _scrollOffsets[sessionId] = offset;
207	  }
208	
209	  /// I/O matrix: "Switch session"/"Switch to already-active session" —
210	  /// a no-op [Right] when [sessionId] is already [ChatReady.sessionId]
211	  /// (the drawer still closes, nothing reloads/re-fetches); otherwise
212	  /// fetches that session's own history via `listMessages` (reused as-is,
213	  /// Code Map) and makes it active, handing [ChatReady.restoreScrollOffset]
214	  /// whatever [recordScrollOffset] last captured for it (`null` if this
215	  /// session was never scrolled in this app run — `ChatScreen`'s own cue
216	  /// to jump to the bottom instead). A no-op while bootstrap hasn't
217	  /// resolved yet, same guard shape as [sendMessage].
218	  Future<Either<Failure, Unit>> switchSession(String sessionId) async {
219	    final current = state;
220	    if (current is! ChatReady) {
221	      return right(unit);
222	    }
223	    if (sessionId == current.sessionId) {
224	      return right(unit);
225	    }
226	    // Review finding: "Cross-session stream leakage" — an AI response
227	    // still streaming into the *old* session must never be left running
228	    // once we switch away from it; its orphaned subscription's
229	    // `onData`/`onDone` would otherwise go on to mutate whichever session
230	    // becomes active next.
231	    await _cancelInFlightSend();
232	    final messagesResult = await _repository.listMessages(sessionId);
233	    if (isClosed) {
234	      return right(unit);
235	    }
236	    return messagesResult.match(
237	      (failure) {
238	        // Review fix: `_cancelInFlightSend()` above only resets the
239	        // internal `_isSending` guard, not the `ChatReady.isSending` the
240	        // composer gates on (`canSend = ... && !state.isSending`) — on a
241	        // failed switch we're staying on `current`, so its stale
242	        // `isSending: true` must be flipped back here or the composer
243	        // would stay disabled for the rest of the app run.
244	        if (!isClosed && current.isSending) {
245	          emit(current.copyWith(isSending: false));
246	        }
247	        return left(failure);
248	      },
249	      (messages) {
250	        if (!isClosed) {
251	          emit(
252	            ChatReady(
253	              sessionId: sessionId,
254	              messages: messages.map(_fromDomain).toList(),
255	              sessions: current.sessions,
256	              restoreScrollOffset: _scrollOffsets[sessionId],
257	              isOffline: _isOffline,
258	            ),
259	          );
260	        }
261	        return right(unit);
262	      },
263	    );
264	  }
265	
266	  /// I/O matrix: "New session online"/"New session offline" — calls
267	  /// `createSession()` (reused as-is, Code Map; already blocked offline
268	  /// at the repository level, Boundaries). On any [Left] (including
269	  /// [Failure.networkOffline]), the current session is left completely
270	  /// untouched — no state is emitted at all, only the [Failure] is handed
271	  /// back for `AppDrawer` to surface as a transient `SnackBar`
272	  /// (Boundaries). On success, the new session opens empty and becomes
273	  /// active, prepended to [ChatReady.sessions].
274	  Future<Either<Failure, Unit>> startNewSession() async {
275	    final current = state;
276	    if (current is! ChatReady) {
277	      return right(unit);
278	    }
279	    // Review finding: "Cross-session stream leakage" — same rationale as
280	    // [switchSession]'s own cancellation above; a brand new session is
281	    // never the same session as [current], so this always needs to run
282	    // (unlike [switchSession], there's no same-session no-op branch to
283	    // skip it for).
284	    await _cancelInFlightSend();
285	    final result = await _repository.createSession();
286	    if (isClosed) {
287	      return right(unit);
288	    }
289	    return result.match(
290	      (failure) {
291	        // Review fix: same stuck-`isSending` risk as [switchSession] — a
292	        // failed `createSession()` leaves `current` active, so its stale
293	        // `isSending: true` (left behind by `_cancelInFlightSend()`
294	        // above, which never emits) must be flipped back here.
295	        if (!isClosed && current.isSending) {
296	          emit(current.copyWith(isSending: false));
297	        }
298	        return left(failure);
299	      },
300	      (session) {
301	        if (!isClosed) {
302	          emit(
303	            ChatReady(
304	              sessionId: session.id,
305	              messages: const [],
306	              sessions: [session, ...current.sessions],
307	              isOffline: _isOffline,
308	            ),
309	          );
310	        }
311	        return right(unit);
312	      },
313	    );
314	  }
315	
316	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
317	    id: message.id,
318	    role: message.role,
319	    content: message.content,
320	    status: message.status,
321	    // spec-6-3 — every message reloaded from `chat-messages-list`/the
322	    // offline cache already has a persisted server id (unlike a message
323	    // created locally mid-session, which only gains one once/if
324	    // `message_created` arrives, Design Notes); [retryMessage] reads this
325	    // off the *user* message immediately preceding a `failed` AI bubble.
326	    serverId: message.id,
327	    createdAt: message.createdAt,
328	    // Review fix (round 2) — re-applies a bookmark save's outcome that
329	    // resolved while this message wasn't part of the live `ChatReady`
330	    // (session switched away mid-save); `idle` default when nothing was
331	    // ever recorded for this `serverId`.
332	    bookmarkState:
333	        _bookmarkStateByServerId[message.id] ?? const BookmarkState.idle(),
334	  );
335	
336	  /// Boundaries: optimistic user bubble, then subscribes to
337	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
338	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
339	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
340	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
341	  ///
342	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
343	  /// or failed — the composer is disabled in that case anyway), while
344	  /// [content] is blank once trimmed, while [_isSending] is already
345	  /// true — this story never races two concurrent sends against the one
346	  /// in-memory session — or while [ChatReady.isOffline] (review finding:
347	  /// the offline lock was UI-only via `_ChatComposer.canSend`, but nothing
348	  /// stopped a direct `sendMessage` caller from firing a real network call
349	  /// while the offline banner's own "novas mensagens bloqueadas" copy says
350	  /// otherwise). Deliberately not keyed off any loaded message's
351	  /// persisted `streaming` status — a message restored from history/cache
352	  /// can legitimately carry that status without a send actually being in
353	  /// flight (I/O matrix: mid-stream drop).
354	  Future<void> sendMessage(String content) async {
355	    final trimmed = content.trim();
356	    if (trimmed.isEmpty) {
357	      return;
358	    }
359	    final current = state;
360	    if (current is! ChatReady) {
361	      return;
362	    }
363	    if (_isSending || current.isOffline) {
364	      return;
365	    }
366	    _isSending = true;
367	
368	    final userMessage = ChatUiMessage(
369	      id: _nextLocalId(),
370	      role: ChatMessageRole.user,
371	      content: trimmed,
372	      status: ChatMessageStatus.complete,
373	    );
374	    final aiMessage = ChatUiMessage(
375	      id: _nextLocalId(),
376	      role: ChatMessageRole.assistant,
377	      content: '',
378	      status: ChatMessageStatus.streaming,
379	    );
380	    emit(
381	      current.copyWith(
382	        messages: [...current.messages, userMessage, aiMessage],
383	        isSending: true,
384	      ),
385	    );
386	
387	    await _consumeStream(
388	      _repository.sendMessage(current.sessionId, trimmed),
389	      userMessageId: userMessage.id,
390	      aiMessageId: aiMessage.id,
391	    );
392	  }
393	
394	  /// spec-6-3 — Boundaries: "Retry resets the *same* bubble (id,
395	  /// position) to `streaming`/empty, then reuses `_applyStreamEvent`/
396	  /// `_markFailed` unchanged — never a second bubble, never a duplicate
397	  /// question." [aiMessageId] must identify an existing `failed` AI
398	  /// bubble; anything else (not found, not `failed`, no preceding user
399	  /// message — shouldn't structurally happen) is a silent no-op, same
400	  /// defensive shape [sendMessage]'s own guards use.
401	  ///
402	  /// Keyed by the preceding user message's [ChatUiMessage.serverId]
403	  /// (Boundaries: "keyed by the user message's persisted id") — calls
404	  /// `ChatRepository.retryMessage` when it's known, or falls back to a
405	  /// full [ChatRepository.sendMessage] resend of that same user content
406	  /// into this exact AI bubble slot when it's `null` (I/O matrix: "Tap
407	  /// retry, no `serverId`" — the stream dropped before `message_created`
408	  /// ever arrived, so the backend never actually persisted the question;
409	  /// Boundaries: "Never calling `chat-messages-retry` with no `serverId`").
410	  /// Reuses [_isSending] verbatim (Boundaries: "A second retry while one
411	  /// is in flight"), so this is a no-op while a send/retry is already in
412	  /// flight — and, like [sendMessage] (review finding), a no-op while
413	  /// [ChatReady.isOffline] too: a failed bubble's retry tap is a separate
414	  /// affordance from the composer, not covered by `_ChatComposer.canSend`
415	  /// alone, so it needs this exact same guard to honor the offline banner.
416	  Future<void> retryMessage(String aiMessageId) async {
417	    final current = state;
418	    if (current is! ChatReady) {
419	      return;
420	    }
421	    if (_isSending || current.isOffline) {
422	      return;
423	    }
424	    final messages = current.messages;
425	    final aiIndex = messages.indexWhere((message) => message.id == aiMessageId);
426	    // Review finding: defensively checks `role` too, even though only an
427	    // assistant message ever reaches `failed` status today — matches this
428	    // guard clause's own already-defensive shape (`aiIndex == -1`, a
429	    // not-found/structurally-impossible case).
430	    if (aiIndex == -1 ||
431	        messages[aiIndex].role != ChatMessageRole.assistant ||
432	        messages[aiIndex].status != ChatMessageStatus.failed) {
433	      return;
434	    }
435	    ChatUiMessage? userMessage;
436	    for (var i = aiIndex - 1; i >= 0; i--) {
437	      if (messages[i].role == ChatMessageRole.user) {
438	        userMessage = messages[i];
439	        break;
440	      }
441	    }
442	    if (userMessage == null) {
443	      return;
444	    }
445	
446	    _isSending = true;
447	    emit(
448	      current.copyWith(
449	        messages: [
450	          for (final message in current.messages)
451	            if (message.id == aiMessageId)
452	              message.copyWith(content: '', status: ChatMessageStatus.streaming)
453	            else
454	              message,
455	        ],
456	        isSending: true,
457	      ),
458	    );
459	
460	    final serverId = userMessage.serverId;
461	    final stream = serverId == null
462	        ? _repository.sendMessage(current.sessionId, userMessage.content)
463	        : _repository.retryMessage(current.sessionId, serverId);
464	    await _consumeStream(
465	      stream,
466	      userMessageId: userMessage.id,
467	      aiMessageId: aiMessageId,
468	    );
469	  }
470	
471	  /// Shared by [sendMessage]/[retryMessage] (Code Map: "extract shared ...
472	  /// helper" extends to this subscribe-and-wait shape too, not just
473	  /// `ChatRemoteDataSource`'s own SSE buffering) — subscribes to [stream],
474	  /// routing every emission through [_applyStreamEvent]/[_markFailed], and
475	  /// resolves once the stream ends (`done`, an in-band error, or a
476	  /// stream-level error), clearing [_isSending]/[ChatReady.isSending]
477	  /// either way via [_finishSending].
478	  Future<void> _consumeStream(
479	    Stream<Either<Failure, ChatStreamEvent>> stream, {
480	    required String userMessageId,
481	    required String aiMessageId,
482	  }) async {
483	    await _sendSubscription?.cancel();
484	    final completer = Completer<void>();
485	    _sendCompleter = completer;
486	    _sendSubscription = stream.listen(
487	      (event) {
488	        event.match(
489	          (failure) => _markFailed(aiMessageId),
490	          (streamEvent) =>
491	              _applyStreamEvent(userMessageId, aiMessageId, streamEvent),
492	        );
493	      },
494	      onError: (Object _, StackTrace _) {
495	        // RNF09: no exception escapes the cubit — a stream-level error
496	        // (shouldn't happen, `ChatRemoteDataSource` never lets one through
497	        // unmapped) still only fails the bubble, never crashes.
498	        _markFailed(aiMessageId);
499	        _finishSending();
500	        if (!completer.isCompleted) {
501	          completer.complete();
502	        }
503	        // Review finding: a stale, already-done subscription reference
504	        // left on `_sendSubscription` made a *later* send/retry's own
505	        // `await _sendSubscription?.cancel()` above hang indefinitely in
506	        // practice (observed via a widget test driving two sends back to
507	        // back) — cleared here (and in the `onDone` branch below)
508	        // exactly where this stream's own lifecycle actually ends,
509	        // rather than relying on cancelling an already-finished
510	        // subscription being an instant no-op.
511	        _sendSubscription = null;
512	        _sendCompleter = null;
513	      },
514	      onDone: () {
515	        _finishSending();
516	        if (!completer.isCompleted) {
517	          completer.complete();
518	        }
519	        _sendSubscription = null;
520	        _sendCompleter = null;
521	      },
522	      cancelOnError: false,
523	    );
524	    await completer.future;
525	  }
526	
527	  /// Clears both the internal re-entrancy guard and the UI-facing
528	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
529	  /// an in-band error, or a stream-level error) — the single place both
530	  /// flip back together.
531	  void _finishSending() {
532	    _isSending = false;
533	    if (isClosed) {
534	      return;
535	    }
536	    final current = state;
537	    if (current is ChatReady) {
538	      emit(current.copyWith(isSending: false));
539	    }
540	  }
541	
542	  void _applyStreamEvent(
543	    String userMessageId,
544	    String aiMessageId,
545	    ChatStreamEvent event,
546	  ) {
547	    if (isClosed) {
548	      return;
549	    }
550	    final current = state;
551	    if (current is! ChatReady) {
552	      return;
553	    }
554	    switch (event) {
555	      case ChatMessageCreatedEvent(userMessageId: final serverId):
556	        // spec-6-3 — Design Notes: "the persisted *user*-message id" is
