36	            dtos.add(ChatSessionDto.fromJson(item as Map<String, dynamic>));
37	          } catch (_) {
38	            // Skip this one malformed item.
39	          }
40	        }
41	        // Review fix: a non-empty response where every item failed to
42	        // decode is a parse failure, not "zero sessions" — returning
43	        // `right([])` here would make `ChatCubit._bootstrap()` believe
44	        // none exist and spuriously `createSession()`, hiding the user's
45	        // real sessions behind a new empty one.
46	        if (data.isNotEmpty && dtos.isEmpty) {
47	          return left(
48	            Failure.malformedResponse(
49	              message: 'All items in listSessions() response failed to decode',
50	            ),
51	          );
52	        }
53	        return right(dtos);
54	      } catch (error) {
55	        // A 200 response that doesn't match the expected shape at all
56	        // (e.g. `data` itself isn't a list) is a client-side parse
57	        // failure, never a backend-sent code — same RNF09 rationale
58	        // `EntriesRemoteDataSource`'s own calls document.
59	        return left(Failure.malformedResponse(message: error.toString()));
60	      }
61	    });
62	  }
