2	// fields they initialize, same convention `entries_repository_impl.dart`
3	// already documents.
4	// ignore_for_file: prefer_initializing_formals
5	import 'package:fpdart/fpdart.dart';
6	import 'package:hive_ce/hive_ce.dart';
7	
8	import '../../../../core/failure/failure.dart';
9	import '../../domain/entities/chat_message.dart';
10	import '../../domain/entities/chat_session.dart';
11	import '../../domain/entities/chat_stream_event.dart';
